using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.0, 1, 0.0, 10.0, DisplayName = "Single item, no tax")]
    [DataRow(10.0, 2, 0.1, 22.0, DisplayName = "Two items, 10% tax")]
    [DataRow(0.0, 5, 0.2, 0.0, DisplayName = "Zero unit price")]
    [DataRow(9.99, 3, 0.08, 32.37, DisplayName = "Fractional price and tax")]
    [DataRow(100.0, 0, 0.1, 0.0, DisplayName = "Zero quantity")]
    [DataRow(50.0, 1, 1.0, 100.0, DisplayName = "100% tax")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"CalculateTotal({unitPrice}, {quantity}, {taxRate})");
    }

    [TestMethod]
    [DataRow(-1.0, 1, 0.1, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.0, -1, 0.1, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.0, 1, -0.1, "taxRate", DisplayName = "Negative tax rate")]
    [DataRow(10.0, 1, 1.5, "taxRate", DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInput_Throws(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> DiscountTestData
    {
        get
        {
            yield return [100m, 0m, 100m, "No discount"];
            yield return [100m, 10m, 90m, "10% off"];
            yield return [200m, 25m, 150m, "25% off"];
            yield return [59.99m, 50m, 29.995m, "50% off fractional price"];
            yield return [100m, 100m, 0m, "Full discount"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, scenario);
    }

    public static IEnumerable<object[]> InvalidDiscountData
    {
        get
        {
            yield return [100m, -1m, "Below zero"];
            yield return [100m, 101m, "Above 100"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidDiscount_Throws(
        decimal price, decimal discountPercent, string scenario)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent),
            scenario);
    }
}

